package dev.votex.config;
import dev.votex.ui.ClickRate;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import java.nio.file.*;
import java.util.List;
import static org.junit.jupiter.api.Assertions.*;
class GlassConfigTest {
 @TempDir Path dir;
 @Test void eightCompleteHudLayoutsSurviveSaveAndReload()throws Exception{Path p=dir.resolve("modules.json");var r=new ModuleRegistry(p);for(var m:ModuleRegistry.HUD_MODULES){r.config().enabled.put(m.id(),true);var position=new ModuleRegistry.Position(480,240);position.viewWidth=640;position.viewHeight=360;r.config().positions.put(m.id(),position);r.config().appearance.put(m.id(),new ModuleRegistry.Appearance());}for(int i=1;i<=8;i++)HudLayouts.save(r.config(),"Layout "+i);r.save();assertTrue(Files.size(p)<ModuleRegistry.MAX_CONFIG_BYTES);var restored=new ModuleRegistry(p);restored.load();assertEquals(8,restored.config().layouts.size());assertTrue(HudLayouts.load(restored.config(),"Layout 8"));assertEquals(ModuleRegistry.HUD_MODULES.size(),restored.config().positions.size());assertEquals(27,restored.config().positions.size());}
 @Test void newSettingsPreserveLegacyModuleAndCoordinateChoices()throws Exception{Path p=dir.resolve("modules.json");String old="{\"schemaVersion\":1,\"enabled\":{\"fps\":false,\"coordinates\":true},\"positions\":{\"coordinates\":{\"x\":220,\"y\":120}},\"appearance\":{\"coordinates\":{\"scale\":130,\"background\":25}}}";Files.writeString(p,old);var r=new ModuleRegistry(p);r.load();assertTrue(r.config().glass.valid());assertFalse(r.enabled("fps"));assertFalse(r.enabled("cps"));assertEquals(220,r.config().positions.get("coordinates").x);assertEquals(100,r.config().appearance.get("coordinates").glassIntensity);assertEquals(old,Files.readString(p));r.save();var reloaded=new ModuleRegistry(p);reloaded.load();assertFalse(reloaded.enabled("fps"));assertEquals(25,reloaded.config().appearance.get("coordinates").background);}
 @Test void allPresetsAndQualityStagesAreValid(){var c=new GlassConfig();for(var p:GlassConfig.Preset.values()){c.preset(p);assertTrue(c.valid());}assertEquals(0,GlassConfig.Quality.OFF.divisor());assertTrue(GlassConfig.Quality.BALANCED.divisor()>GlassConfig.Quality.ULTRA.divisor());c.refraction=101;assertFalse(c.valid());c.refraction=20;c.tint="javascript:bad";assertFalse(c.valid());}
 @Test void savedLayoutsDoNotShareMutableObjectsAndLeaveNonHudFeaturesAlone(){var c=new ModuleRegistry.Config();c.positions.put("fps",new ModuleRegistry.Position(200,120));var a=new ModuleRegistry.Appearance();a.glassIntensity=35;c.appearance.put("fps",a);c.enabled.put("item_physics",false);HudLayouts.save(c,"Layout 1");c.positions.get("fps").x=20;c.appearance.get("fps").glassIntensity=90;c.enabled.put("item_physics",true);assertTrue(HudLayouts.load(c,"Layout 1"));assertEquals(200,c.positions.get("fps").x);assertEquals(35,c.appearance.get("fps").glassIntensity);assertTrue(c.enabled.get("item_physics"));c.positions.get("fps").x=50;assertEquals(200,c.layouts.get("Layout 1").positions.get("fps").x);assertFalse(HudLayouts.load(c,"Layout 2"));}
 @Test void resolutionMappingKeepsLegacyAndRelativeEdges(){assertEquals(220,HudLayouts.resolve(220,0,1280,100));assertEquals(1180,HudLayouts.resolve(540,640,1280,100));assertEquals(4,HudLayouts.snap(7,100,640,List.of()));assertEquals(206,HudLayouts.snap(204,100,640,List.of(200)));assertEquals(200,HudLayouts.snap(200,100,640,List.of(200)));}
 @Test void invalidNewSettingsPreserveOriginalFile()throws Exception{Path p=dir.resolve("modules.json");String raw="{\"schemaVersion\":1,\"enabled\":{},\"glass\":{\"refraction\":1000}}";Files.writeString(p,raw);assertThrows(java.io.IOException.class,()->new ModuleRegistry(p).load());assertEquals(raw,Files.readString(p));}
 @Test void cpsCountsActualPressesInLastSecondAndSeparatesButtons(){var r=new ClickRate();r.press(0,1_000_000_000L);r.press(1,1_100_000_000L);r.press(0,1_400_000_000L);assertEquals(2,r.count(0,1_500_000_000L));assertEquals(1,r.count(1,1_500_000_000L));assertEquals(1,r.count(0,2_000_000_000L));assertEquals(0,r.count(1,2_100_000_000L));}
}
